def test_auto_close_retires_the_live_request_when_an_answered_one_shares_the_sender(mesh: Mesh) -> None:
    mesh.run("send", "first", "worker", pane=PLANNER_PANE, stdin="a\n")
    mesh.run("reply", "1", "planner", "--no-ring", pane=WORKER_PANE, stdin="done\n")  # 001 answered by reply
    mesh.run("send", "second", "worker", pane=PLANNER_PANE, stdin="b\n")  # 002 still live

    result = mesh.run("send", "re-002-update", "planner", pane=WORKER_PANE, stdin="delta\n")

    assert result.returncode == 0, result.stderr
    closed = [l for l in log_lines(mesh) if l["event"] == "closed"]
    assert len(closed) == 1
    assert closed[0]["id"] == "002-second"
    status = mesh.run("status", "planner", pane=PLANNER_PANE)
    # the worker's reply to 001 sits unread in planner's inbox - it may list;
    # neither request may list as pending
    assert "pending  001-first" not in status.stdout
    assert "pending  002-second" not in status.stdout


