# --- member control: launchers, spawn, restart, inspect, interrupt, retire, adopt ---

LAUNCHERS_TOML = '''[local]
command = ["local-claude"]
harness = "claude"
resume = ["--resume", "{session}"]
billed = false

[ccc]
command = ["/opt/agent/bin/ccc"]
harness = "claude"
env = { COMMIT_AUTHORISED = "1", MODEL_BACKEND = "gateway" }
resume = ["--resume", "{session}"]
billed = true

[no-resume]
command = ["some-agent"]
harness = "claude"
'''


def write_launchers(mesh: Mesh, text: str = LAUNCHERS_TOML) -> None:
    (mesh.root / "launchers.toml").write_text(text)


def test_parse_launchers_accepts_the_user_written_shape() -> None:
    helper = load_helper(HELPER)

    launchers, problems = helper.parse_launchers(LAUNCHERS_TOML, Path("launchers.toml"))

    assert problems == []
    assert launchers["local"].command == ("local-claude",)
    assert launchers["local"].harness == "claude"
    assert launchers["local"].resume == ("--resume", "{session}")
    assert launchers["local"].billed is False
    assert launchers["ccc"].env == {"COMMIT_AUTHORISED": "1", "MODEL_BACKEND": "gateway"}
    assert launchers["ccc"].billed is True
    assert launchers["no-resume"].resume is None


@pytest.mark.parametrize(
    ("entry", "complaint"),
    [
        ('[x]\ncommand = "local-claude"\nharness = "claude"\n', "never a shell line"),
        ('[x]\ncommand = ["a; b"]\nharness = "claude"\n', "shell metacharacters"),
        ('[x]\ncommand = ["K=V local"]\nharness = "claude"\n', "plain command name"),
        ('[x]\ncommand = ["ccc"]\n', "harness must be"),
        ('[x]\ncommand = ["ccc"]\nharness = "claude"\nresume = ["--resume"]\n', "session} placeholder"),
        ('[x]\ncommand = ["ccc"]\nharness = "claude"\nbilled = "yes"\n', "billed"),
        ('[x]\ncommand = ["ccc"]\nharness = "claude"\nsession = "y"\n', "unknown keys"),
        ('[x]\ncommand = ["cc\'c"]\nharness = "claude"\n', "apostrophe"),
        ('[x]\ncommand = ["ccc"]\nharness = "claude"\nenv = { K = 1 }\n', "string to string"),
    ],
)
def test_parse_launchers_refuses_what_cannot_become_a_restore_argv(entry: str, complaint: str) -> None:
    helper = load_helper(HELPER)

    launchers, problems = helper.parse_launchers(entry, Path("launchers.toml"))

    assert launchers == {}
    assert any(complaint in problem for problem in problems), problems


def test_resume_argv_renders_env_command_and_resume() -> None:
    helper = load_helper(HELPER)
    launchers, _ = helper.parse_launchers(LAUNCHERS_TOML, Path("x"))

    argv = helper.resume_argv_for(launchers["ccc"], "sess-9")

    assert argv == (
        "env", "COMMIT_AUTHORISED=1", "MODEL_BACKEND=gateway",
        "/opt/agent/bin/ccc", "--resume", "sess-9",
    )
    assert helper.resume_argv_for(launchers["local"], "s1") == ("env", "local-claude", "--resume", "s1")
    assert helper.resume_argv_for(launchers["no-resume"], "s1") == ("env", "some-agent")


def test_launch_shell_line_is_the_same_argv_the_restore_registers() -> None:
    helper = load_helper(HELPER)
    launchers, _ = helper.parse_launchers(LAUNCHERS_TOML, Path("x"))

    line = helper.launch_shell_line(launchers["ccc"], ("--resume", "sess-9"))
    bare = helper.launch_shell_line(launchers["local"])

    assert line == "env COMMIT_AUTHORISED=1 MODEL_BACKEND=gateway /opt/agent/bin/ccc --resume sess-9"
    # `env` leads even with no pairs: the restore argv and the launch line are one shape
    assert bare == "env local-claude"


def test_join_line_carries_the_spawn_flags_and_intro() -> None:
    helper = load_helper(HELPER)

    line = helper.join_line_for(
        Path("/mesh"), "worker-2", "worker orchestrator", "local", "planner", "w9:t1", None
    )
    with_intro = helper.join_line_for(
        Path("/mesh"), "worker-2", "worker", "local", "planner", "w9:t1", "Load the orchestrator skill"
    )

    assert line == (
        "/mesh/bin/mailbox join worker-2 --role 'worker orchestrator'"
        " --launcher local --spawned-by planner --tab w9:t1"
    )
    assert with_intro == line.replace("'worker orchestrator'", "worker") + "\nLoad the orchestrator skill"


def test_spawn_starts_a_member_through_an_approved_launcher(
    mesh: Mesh, helper: ModuleType, monkeypatch: pytest.MonkeyPatch
) -> None:
    write_launchers(mesh)
    monkeypatch.setenv("HERDR_PANE_ID", PLANNER_PANE)
    monkeypatch.setenv("HERDR_WORKSPACE_ID", "w9")
    # the first tab the fake creates in w9 is w9:t1 with pane w9:p1
    mesh.herdr.set("launches", {"w9:p1": {"session": "sess-new"}})

    result = CliRunner().invoke(
        helper.app, ["spawn", "worker-2", "--role", "worker", "--launcher", "local"]
    )

    assert result.exit_code == 0, result.output
    calls = mesh.herdr.calls()
    assert ["tab", "create", "--workspace", "w9", "--label", "worker-2", "--no-focus"] in calls
    assert ["pane", "rename", "w9:p1", "worker-2"] in calls
    assert ["pane", "run", "w9:p1", "env local-claude"] in calls
    assert ["pane", "report-agent-session", "w9:p1", "--source", "mailbox", "--agent", "claude",
            "--agent-session-id", "sess-new", "--", "env", "local-claude", "--resume", "sess-new"] in calls
    member = (mesh.root / "members" / "worker-2").read_text()
    assert "launcher=local" in member
    assert "spawned-by=planner" in member
    assert "tab=w9:t1" in member
    assert "harness-session=sess-new" in member
    assert "restore registered: env local-claude --resume sess-new" in result.stdout
    assert "spawned worker-2 in tab w9:t1 (pane w9:p1) through launcher local" in result.stdout
    event = [l for l in log_lines(mesh) if l["event"] == "spawn"][-1]
    assert event["member"] == "worker-2" and event["by"] == "planner"
    assert event["launcher"] == "local" and event["session"] == "sess-new"


