def joined_worker_with_launcher(mesh: Mesh, *, launcher: str = "local") -> None:
    """Re-join worker from its own pane carrying the spawn flags, with a recorded session."""
    write_launchers(mesh)
    mesh.herdr.set("agent_sessions", {"worker": "sess-old"})
    mesh.herdr.set("tabs", {"w9:t9": {"label": "worker", "workspace": "w9", "pane": WORKER_PANE}})
    result = mesh.run(
        "join", "worker", "--role", "worker", "--launcher", launcher,
        "--spawned-by", "planner", "--tab", "w9:t9", pane=WORKER_PANE,
    )
    assert result.returncode == 0, result.stderr


def stage_worker_agent(mesh: Mesh, *, status: str = "idle", session: str = "sess-old") -> None:
    """A live pane-keyed agent at worker's seat, as a launch leaves behind."""
    mesh.herdr.set("pane_agents", {WORKER_PANE: {"agent": "claude", "status": status, "session": session}})


def test_restart_relaunches_the_recorded_session_and_refreshes_the_record(
    mesh: Mesh, helper: ModuleType, monkeypatch: pytest.MonkeyPatch
) -> None:
    joined_worker_with_launcher(mesh)
    stage_worker_agent(mesh)
    # the relaunched agent comes back with a new harness session
    mesh.herdr.set("launches", {WORKER_PANE: {"session": "sess-new"}})
    monkeypatch.setenv("HERDR_PANE_ID", PLANNER_PANE)

    result = CliRunner().invoke(helper.app, ["restart", "worker"])

    assert result.exit_code == 0, result.output
    calls = mesh.herdr.calls()
    assert ["agent", "send-keys", WORKER_PANE, "esc"] in calls
    assert ["pane", "run", WORKER_PANE, "env local-claude --resume sess-old"] in calls
    assert ["pane", "report-agent-session", WORKER_PANE, "--source", "mailbox", "--agent", "claude",
            "--agent-session-id", "sess-new", "--", "env", "local-claude", "--resume", "sess-new"] in calls
    assert "harness session refreshed: sess-old -> sess-new" in result.stdout
    assert "harness-session=sess-new" in (mesh.root / "members" / "worker").read_text()
    assert "restore registered: env local-claude --resume sess-new" in result.stdout
    assert "you were restarted by planner" in " ".join(
        str(call[3]) for call in calls if call[1] == "prompt"
    )
    event = [l for l in log_lines(mesh) if l["event"] == "restart"][-1]
    assert event["member"] == "worker" and event["by"] == "planner" and event["session"] == "sess-new"


