def test_next_deadline_computes_the_earliest_wake() -> None:
    helper = load_helper(HELPER)
    clock = {"t": 10_000.0}

    def now() -> float:
        return clock["t"]

    watcher = helper.Watcher(make_policy(helper, {"w": (rule(helper, "unread", after=600),)}), clock=now)
    watcher.observe("w", observe(helper, status="idle", unread_oldest=now() - 100, unread_count=1), now())

    assert watcher.next_deadline() == now() - 100 + 600

    firings = watcher.due(now() + 501)
