class FakeEventsConnection:
    """The loop-facing events seam: scripted envelopes, recorded timeouts."""

    def __init__(self, script: list[dict]):
        self.script = list(script)
        self.timeouts: list[float] = []

    def connect(self) -> None:
        pass

    def next_event(self, timeout_s: float) -> dict | None:
        self.timeouts.append(timeout_s)
        return self.script.pop(0) if self.script else None

    def close(self) -> None:
        pass


def test_the_loop_catches_up_on_a_drop_with_backoff(mesh: Mesh) -> None:
    helper = load_helper(HELPER)
    write_watchdog(mesh)
    policy = helper.load_watchdog_policy(mesh.root, required=True)
    sleeps: list[float] = []
    attempts: list[int] = []

    def connect(path, subs):
        attempts.append(len(attempts))
        if len(attempts) < 3:
            raise helper.ConnectionDropped("herdr closed the socket")
        return FakeEventsConnection([])

    loop = helper.WatchdogLoop(
        mesh.root, policy, clock=lambda: 0.0, sleep=sleeps.append, connect=connect,
        socket_info=lambda: (Path("x"), 22),
    )
    loop.backoff_reconnect()

    assert sleeps == [0.5, 1.0, 2.0]  # a sleep before each attempt, exponential
    assert len(attempts) == 3
    assert (mesh.root / "watchdog-state.json").is_file()  # the reconnect ran a catch-up pass


