def test_watchdog_init_writes_each_shipped_template(mesh: Mesh) -> None:
    overseer = mesh.run(
        "watchdog", "init", "--template", "overseer-worker",
        "--overseer", "planner", "--worker", "worker", pane=PLANNER_PANE,
    )
    assert overseer.returncode == 0, overseer.stderr
    text = (mesh.root / "watchdog.toml").read_text()
    assert "[member.worker]" in text and "escalate_to = \"planner\"" in text
    assert "idle" not in text.split("[member.planner]")[1]  # the expensive member gets no idle rule

    again = mesh.run("watchdog", "init", "--template", "peers", pane=PLANNER_PANE)
    assert again.returncode != 0
    assert "refuses to overwrite" in again.stderr

    (mesh.root / "watchdog.toml").unlink()
    peers = mesh.run("watchdog", "init", "--template", "peers", pane=PLANNER_PANE)
    assert peers.returncode == 0, peers.stderr
    peers_text = (mesh.root / "watchdog.toml").read_text()
    assert "do = \"poke\"" in peers_text and "do = \"interrupt\"" in peers_text

    (mesh.root / "watchdog.toml").unlink()
    log_only = mesh.run("watchdog", "init", "--template", "log-only", pane=PLANNER_PANE)
    assert log_only.returncode == 0, log_only.stderr
    assert (mesh.root / "watchdog.toml").read_text().count('do = "log"') >= 12

    (mesh.root / "watchdog.toml").unlink()
    unknown = mesh.run("watchdog", "init", "--template", "strict", pane=PLANNER_PANE)
    assert unknown.returncode != 0
    assert "unknown template" in unknown.stderr


