def test_the_watchdog_restart_action_runs_the_restart_core(
    mesh: Mesh, helper: ModuleType, monkeypatch: pytest.MonkeyPatch
) -> None:
    joined_worker_with_launcher(mesh)
    stage_worker_agent(mesh, status="idle")
    write_watchdog(mesh, '''interval = "5m"

[member.worker]
error = { match = ["API Error"], do = "restart" }
''')
    mesh.herdr.set("pane_screens", {WORKER_PANE: "API Error: issue with the selected model\n" + composer_box("❯")})
    mesh.herdr.clear_log()

    result = mesh.run("watchdog", "run", "--once", pane=PLANNER_PANE)

    assert result.returncode == 0, result.stderr
    calls = mesh.herdr.calls()
    assert ["agent", "send-keys", WORKER_PANE, "esc"] in calls
    assert ["pane", "run", WORKER_PANE, "env local-claude --resume sess-old"] in calls
    wake = next(str(call[3]) for call in calls if call[1] == "prompt" and "restarted" in str(call[3]))
    assert "restarted by watchdog" in wake
    event = [l for l in log_lines(mesh) if l["event"] == "restart"][-1]
    assert event["by"] == "watchdog"


def test_a_deferred_ring_is_logged_not_counted_and_retries(mesh: Mesh, helper: ModuleType) -> None:
    write_watchdog(mesh, '''interval = "5m"

[member.worker]
unread = { after = "10m", do = "poke" }
''')
    assert mesh.run("send", "handover", "worker", pane=PLANNER_PANE, stdin="take this\n").returncode == 0
    age_unread_mail(mesh, "worker", 700)
    # the worker's human is mid-draft: the wake line does not submit
    mesh.herdr.set("pane_screens", {WORKER_PANE: composer_box("❯ as i was saying the e")})

    result = mesh.run("watchdog", "run", "--once", pane=PLANNER_PANE)

    assert result.returncode == 0, result.stderr
    event = [l for l in log_lines(mesh) if l["event"] == "watchdog"][-1]
    assert event["check"] == "unread" and "not rung" in event["outcome"]

